-- AMB gemach management - Neon schema (multi-tenant: every row belongs to a gemach)
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE gemachim (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text, base_cash numeric(14,2) NOT NULL DEFAULT 0, alert_prefs jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK (role IN ('owner','gemach')), gemach_id uuid REFERENCES gemachim(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), CHECK ((role='owner' AND gemach_id IS NULL) OR (role='gemach' AND gemach_id IS NOT NULL)));
CREATE TABLE loans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gemach_id uuid NOT NULL REFERENCES gemachim(id) ON DELETE CASCADE, first_name text NOT NULL, last_name text, tz text, email text, phone text, city text, street text, house text, bank text, branch text, account text, guarantor1_name text, guarantor1_tz text, guarantor1_phone text, guarantor2_name text, guarantor2_tz text, guarantor2_phone text, child_name text, child_tz text, start_date date NOT NULL, charge_day int NOT NULL DEFAULT 1 CHECK (charge_day BETWEEN 1 AND 31), amount numeric(14,2) NOT NULL, installments int NOT NULL CHECK (installments > 0), has_standing_order boolean NOT NULL DEFAULT false, is_existing boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX loans_gemach_idx ON loans(gemach_id);
CREATE INDEX loans_tz_idx ON loans(gemach_id, tz);
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), loan_id uuid NOT NULL REFERENCES loans(id) ON DELETE CASCADE, paid_on date NOT NULL, amount numeric(14,2) NOT NULL, source text NOT NULL DEFAULT 'manual', returned boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX payments_loan_idx ON payments(loan_id);
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), loan_id uuid NOT NULL REFERENCES loans(id) ON DELETE CASCADE, file_name text NOT NULL, storage_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gemach_id uuid NOT NULL REFERENCES gemachim(id) ON DELETE CASCADE, loan_id uuid REFERENCES loans(id) ON DELETE SET NULL, title text NOT NULL, kind text NOT NULL DEFAULT 'task', due_date date NOT NULL, done boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tasks_gemach_idx ON tasks(gemach_id, due_date);
